import{_ as i,c as e,o as a,a3 as t}from"./chunks/framework.MI-M1z4O.js";const p=JSON.parse('{"title":"Linux Electron デバッグクラッシュ（ENOSPC inotify watcher 上限超過）トラブルシューティング","description":"Linux 環境で Electron アプリケーションのデバッグ実行中に発生する ENOSPC（System limit for number of file watchers reached）カーネル inotify 上限超過の原因分析および sysctl 永続チューニングガイドです。","frontmatter":{"title":"Linux Electron デバッグクラッシュ（ENOSPC inotify watcher 上限超過）トラブルシューティング","description":"Linux 環境で Electron アプリケーションのデバッグ実行中に発生する ENOSPC（System limit for number of file watchers reached）カーネル inotify 上限超過の原因分析および sysctl 永続チューニングガイドです。","head":[["meta",{"name":"keywords","content":"SyncETA, Electron, Linux, ENOSPC, inotify, max_user_watches, max_user_instances, chokidar, デバッグ, トラブルシューティング"}],["meta",{"property":"og:title","content":"Linux Electron デバッグクラッシュ（ENOSPC inotify watcher 上限超過）トラブルシューティング | Empasy Docs"}],["meta",{"property":"og:description","content":"Linux カーネル fs.inotify.max_user_watches 上限の引き上げおよび CHOKIDAR_USEPOLLING フォールバックによる Electron 開発サーバークラッシュの解決ガイドです。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/logs/20250827_debugCrash"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/logs/20250827_debugCrash"}]],"sort":400},"headers":[],"relativePath":"ja/logs/20250827_debugCrash.md","filePath":"ja/logs/20250827_debugCrash.md","lastUpdated":1795293539000}'),n={name:"ja/logs/20250827_debugCrash.md"};function l(h,s,r,o,d,c){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="linux-electron-デバッグクラッシュ-enospc-system-limit-for-number-of-file-watchers-reached-トラブルシューティング" tabindex="-1">Linux Electron デバッグクラッシュ（<code>ENOSPC: System limit for number of file watchers reached</code>）トラブルシューティング <a class="header-anchor" href="#linux-electron-デバッグクラッシュ-enospc-system-limit-for-number-of-file-watchers-reached-トラブルシューティング" aria-label="Permalink to “Linux Electron デバッグクラッシュ（ENOSPC: System limit for number of file watchers reached）トラブルシューティング”">​</a></h1><h2 id="_1-障害現象および原因分析-rca" tabindex="-1">1. 障害現象および原因分析（RCA） <a class="header-anchor" href="#_1-障害現象および原因分析-rca" aria-label="Permalink to “1. 障害現象および原因分析（RCA）”">​</a></h2><p>Linux デスクトップ開発環境で SyncETA Electron アプリケーションをデバッグモード（<code>yarn dev:debug</code>）で起動する際、Vite/Chokidar のファイル変更監視機能が <code>node_modules</code> およびワークスペース配下ディレクトリのファイルディスクリプタを監視する過程で Linux カーネルのデフォルト <code>inotify</code> ウォッチャー上限（<code>8192</code> または <code>65536</code>）を超過し、<code>ENOSPC: System limit for number of file watchers reached</code> 例外とともにプロセスが異常終了する現象です。</p><hr><h2 id="_2-解決方法-1-linux-カーネル-inotify-watcher-上限の引き上げ-推奨" tabindex="-1">2. 解決方法 1: Linux カーネル <code>inotify</code> Watcher 上限の引き上げ（推奨） <a class="header-anchor" href="#_2-解決方法-1-linux-カーネル-inotify-watcher-上限の引き上げ-推奨" aria-label="Permalink to “2. 解決方法 1: Linux カーネル inotify Watcher 上限の引き上げ（推奨）”">​</a></h2><h3 id="_2-1-現在のカーネル設定値の確認" tabindex="-1">2.1 現在のカーネル設定値の確認 <a class="header-anchor" href="#_2-1-現在のカーネル設定値の確認" aria-label="Permalink to “2.1 現在のカーネル設定値の確認”">​</a></h3><div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/fs/inotify/max_user_watches</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/fs/inotify/max_user_instances</span></span></code></pre></div><h3 id="_2-2-ランタイム即時引き上げの適用-一時適用" tabindex="-1">2.2 ランタイム即時引き上げの適用（一時適用） <a class="header-anchor" href="#_2-2-ランタイム即時引き上げの適用-一時適用" aria-label="Permalink to “2.2 ランタイム即時引き上げの適用（一時適用）”">​</a></h3><div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fs.inotify.max_user_watches=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">524288</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fs.inotify.max_user_instances=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span></span></code></pre></div><h3 id="_2-3-永続設定の適用-etc-sysctl-d-99-inotify-conf" tabindex="-1">2.3 永続設定の適用（<code>/etc/sysctl.d/99-inotify.conf</code>） <a class="header-anchor" href="#_2-3-永続設定の適用-etc-sysctl-d-99-inotify-conf" aria-label="Permalink to “2.3 永続設定の適用（/etc/sysctl.d/99-inotify.conf）”">​</a></h3><p>システム再起動後も設定が維持されるよう、<code>sysctl.d</code> 設定ファイルを登録します。</p><div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fs.inotify.max_user_watches=524288&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fs.inotify.max_user_instances=1024&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span></code></pre></div><p>設定反映後、<code>yarn dev:debug</code> を再実行して正常に起動するかどうかを確認します。</p><hr><h2 id="_3-解決方法-2-カーネルパラメータ変更不可時の-polling-モード切り替え-コンテナ-制限環境" tabindex="-1">3. 解決方法 2: カーネルパラメータ変更不可時の Polling モード切り替え（コンテナ／制限環境） <a class="header-anchor" href="#_3-解決方法-2-カーネルパラメータ変更不可時の-polling-モード切り替え-コンテナ-制限環境" aria-label="Permalink to “3. 解決方法 2: カーネルパラメータ変更不可時の Polling モード切り替え（コンテナ／制限環境）”">​</a></h2><p><code>sudo</code> 権限がない、またはカーネルパラメータの変更が制限されている CI コンテナ環境では、ファイルシステムイベントの代わりにポーリング（Polling）モードを有効化します。</p><h3 id="_3-1-単発環境変数での実行" tabindex="-1">3.1 単発環境変数での実行 <a class="header-anchor" href="#_3-1-単発環境変数での実行" aria-label="Permalink to “3.1 単発環境変数での実行”">​</a></h3><div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHOKIDAR_USEPOLLING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CHOKIDAR_INTERVAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">800</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:debug</span></span></code></pre></div><h3 id="_3-2-ide-run-debug-configuration-への登録" tabindex="-1">3.2 IDE Run/Debug Configuration への登録 <a class="header-anchor" href="#_3-2-ide-run-debug-configuration-への登録" aria-label="Permalink to “3.2 IDE Run/Debug Configuration への登録”">​</a></h3><p>IntelliJ IDEA の <strong>Run/Debug Configurations -&gt; Environment variables</strong> 項目に以下の変数を固定登録して常時適用できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">環境変数キー</th><th style="text-align:left;">推奨設定値</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CHOKIDAR_USEPOLLING</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">OS カーネル <code>inotify</code> の代わりに定期的なファイル状態ポーリングを有効化</td></tr><tr><td style="text-align:left;"><code>CHOKIDAR_INTERVAL</code></td><td style="text-align:left;"><code>800</code></td><td style="text-align:left;">ファイル変更検知のポーリング周期（<code>ms</code> 単位、CPU 負荷を最小化）</td></tr></tbody></table>`,21)])])}const g=i(n,[["render",l]]);export{p as __pageData,g as default};
